css:
:root {
  /* Nordic Calm Theme - icy minimalism and misty fjords */
  --bg-primary: #f5f8fb;
  --bg-alt: #e6edf3;
  --bg-hover: #d7e4ee;
  --text-primary: #12202c;
  --text-primary-rgb: 18, 32, 44;
  --text-secondary: #4a6274;
  --border: #b8c9d8;
  --accent: #4fb0c6;
  --accent-rgb: 79, 176, 198;
  --accent-hover: #3c8fa3;
  --frost: rgba(255, 255, 255, 0.8);
}

[data-theme="dark"] {
  --bg-primary: #0b1118;
  --bg-alt: #0f1a25;
  --bg-hover: #132231;
  --text-primary: #e8f3fb;
  --text-primary-rgb: 232, 243, 251;
  --text-secondary: #b8c9d8;
  --border: #3c5062;
  --accent: #7fd1e6;
  --accent-rgb: 127, 209, 230;
  --accent-hover: #9fe4f3;
  --frost: rgba(255, 255, 255, 0.06);
}

body {
  background: linear-gradient(160deg, #f5f8fb 0%, #e6edf3 60%, #d7e4ee 100%);
}

.card {
  background: var(--frost);
  border: 1px solid var(--border);
  box-shadow: 0 14px 30px rgba(var(--text-primary-rgb), 0.12);
  backdrop-filter: blur(6px);
}

.tag {
  background: rgba(var(--accent-rgb), 0.12);
  color: var(--text-primary);
  border: 1px solid var(--accent);
  text-transform: uppercase;
  letter-spacing: 0.6px;
}
